#!/usr/bin/env python3
"""Archive the completed FFI-call campaign without changing measured data."""
import argparse
from datetime import datetime, timezone
import difflib
import hashlib
import json
from pathlib import Path
import re
import subprocess

ROOT = Path('/Users/0x1/Documents/htdocs/altbak.pub')
COMPILER = ROOT.parent / 'gopurs/gopurs'
WORK = ROOT / 'var/benchmark/go-ffi-calls-20261126'
OUTPUT = ROOT / 'docs/benchmark-results/2026-11-26-go-ffi-calls.json'


def sha(data):
    return hashlib.sha256(data).hexdigest()


def verify(path, expected):
    path = Path(path)
    if sha(path.read_bytes()) != expected:
        raise ValueError('Hash mismatch: ' + str(path))


def artifact(path, omit=False):
    data = Path(path).read_bytes()
    result = {'sha256': sha(data), 'size_bytes': len(data)}
    if omit:
        result['text_omitted'] = 'Large generated overlay; exact hashes and the retained overlay patch identify its contents.'
    else:
        result['text'] = data.decode('utf-8')
    return result


def git(root, *args):
    return subprocess.check_output(['git', '-C', str(root), *args])


def verify_campaign(campaign, baseline):
    for name, expected in campaign['compiler_snapshot']['files_sha256'].items():
        verify(name, expected)
    verify_count = 0
    for name, expected in campaign['frozen_reference']['source_sha256'].items():
        verify(ROOT / name, expected)
        verify_count += 1
    for name, expected in campaign['frozen_reference']['reference_files_sha256'].items():
        verify(name, expected)
    for group in ['files', 'sources']:
        for item in baseline[group].values():
            verify(item['path'], item['sha256'])
    for entry in campaign['core_manifest']['plan']:
        verify(entry['manifest'], entry['manifest_sha256'])
        for name, expected in entry['payload_sha256'].items():
            verify(name, expected)
    all_cases = campaign['all_campaign']
    for variant, directory in all_cases['workspaces'].items():
        verify(Path(directory) / 'manifest.json', all_cases['manifest_sha256'][variant])
        verify(Path(directory) / 'benchmark', all_cases['executable_sha256'][variant])
    c_build = campaign['frozen_reference']['c_build']
    verify(c_build['manifest_path'], c_build['manifest_sha256'])
    for name, expected in c_build['payload_sha256'].items():
        verify(name, expected)
    for name, expected in c_build['source_sha256'].items():
        verify(ROOT / name, expected)
    verify(WORK / 'campaign/core/results.json', campaign['core_manifest']['results_sha256'])
    return {'compiler_files': len(campaign['compiler_snapshot']['files_sha256']),
            'frozen_current_files': verify_count}



def input_proofs(campaign):
    c_sha = campaign['frozen_reference']['c_build']['manifest']['binary_sha256']
    results = {}
    expected = {entry['key']: entry['executable_sha256'] for entry in campaign['core_manifest']['plan']}
    for variant in ['before', 'after']:
        directory = WORK / 'proofs' / (variant + '-inputs')
        manifest = json.loads((directory / 'manifest.json').read_text())
        if (manifest['cases'], manifest['opaque_calls_per_action'], manifest['c_binary_sha256']) != (88, 1, c_sha):
            raise ValueError('Invalid input proof: ' + variant)
        if manifest['binary_sha256'] != expected[variant]:
            raise ValueError('Input proof uses a different binary: ' + variant)
        verify(Path(manifest['build']) / 'benchmark', manifest['binary_sha256'])
        verify(manifest['generated_source'], manifest['generated_sha256'])
        verify(directory / 'opaque-override.go', manifest['override_sha256'])
        inputs = json.loads((directory / 'inputs.json').read_text())
        output = (directory / 'stdout.txt').read_text()
        if len(inputs) != 88 or len(output.splitlines()) != 88 or (directory / 'stderr.txt').read_text():
            raise ValueError('Incomplete input proof: ' + variant)
        results[variant] = {'inputs': inputs, 'stdout': output}
    if results['before'] != results['after']:
        raise ValueError('Runtime inputs or results differ')
    return {'before': 'before-inputs', 'after': 'after-inputs', 'variants_per_build': 88,
            'opaque_calls_per_action': 1, 'same_outputs_and_inputs': True, 'c_binary_sha256': c_sha}


def compiler_changes(baseline):
    names = set(git(COMPILER, 'ls-files', '--cached', '--others', '--exclude-standard').decode().splitlines())
    names.update(baseline['sources'])
    changed, before, after, patch = [], {}, {}, ''
    for name in sorted(names):
        if not (name.startswith(('src/', 'runtime/', 'tools/', 'docs/')) or name in
                ['CHANGELOG.md', 'README.md', 'package.json', 'package-lock.json',
                 'spago.yaml', 'spago.lock', 'bootstrap-sources.json']):
            continue
        if Path(name).suffix not in {'.purs', '.go', '.js', '.rs', '.mjs', '.md', '.json', '.yaml', '.lock'}:
            continue
        old_entry = baseline['sources'].get(name)
        old = Path(old_entry['path']).read_text() if old_entry else ''
        current = COMPILER / name
        new = current.read_text() if current.exists() else ''
        if old == new:
            continue
        changed.append(name)
        if old_entry:
            before[name] = artifact(old_entry['path'])
        after[name] = artifact(current) if current.exists() else {'deleted': True}
        patch += ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True),
                                             fromfile='a/' + name, tofile='b/' + name))
    if not changed:
        raise ValueError('Expected compiler changes from the original snapshot')
    return changed, before, after, {'sha256': sha(patch.encode()), 'text': patch}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--write', action='store_true')
    args = parser.parse_args()
    campaign = json.loads((WORK / 'campaign/results.json').read_text())
    baseline = json.loads((WORK / 'compiler-before/manifest.json').read_text())
    checks = verify_campaign(campaign, baseline)
    inputs = input_proofs(campaign)
    changed, before, after, patch = compiler_changes(baseline)
    final = json.loads((WORK / 'validation-summary.json').read_text())
    logs = {str(p.relative_to(WORK)): artifact(p) for pattern in
            ['validation-logs/*.log', 'logs/*.log', 'after-core/logs/*.log', 'after-all/logs/*.log']
            for p in sorted(WORK.glob(pattern))}
    if final.get('status') != 'passed':
        raise ValueError('Root-approved final validation must be passed')
    for item in final.get('required_node_logs', []):
        value = (WORK / item['path']).read_text()
        if not re.search(r'^ℹ pass ' + str(item['passed']) + r'$', value, re.M) or not re.search(r'^ℹ fail 0$', value, re.M):
            raise ValueError('Final test log failed: ' + item['path'])
    verify(Path(__file__).with_name('measure-pair.py'), campaign['wrapper_sha256'])
    proof_files = {}
    for path in sorted((WORK / 'proofs').rglob('*')):
        if path.is_file() and path.suffix in {'.json', '.go', '.py', '.stdout', '.stderr', '.txt', '.patch', '.log'}:
            proof_files[str(path.relative_to(WORK / 'proofs'))] = artifact(path, path.name == 'opaque-override.go')
    campaign_files = {str(p.relative_to(WORK)): artifact(p) for p in sorted((WORK / 'campaign').rglob('*'))
                      if p.is_file() and p.name != 'results.json'}
    collectors = {name: artifact(ROOT / name) for name in
                  ['bin/benchmark/measure.py', 'bin/benchmark/js-ratios.py',
                   'bin/benchmark/compare-core.py', 'bin/benchmark/publish.py', 'bin/benchmark/validate.py']}
    archive = {
        'date': '2026-11-26', 'finalized_on': '2026-11-26',
        'archived_at_utc': datetime.now(timezone.utc).isoformat(), 'campaign': campaign,
        'compiler': {'baseline_head': baseline['head'], 'baseline_kind': 'frozen working tree',
                     'head_at_archive': git(COMPILER, 'rev-parse', 'HEAD').decode().strip(),
                     'status_at_archive': git(COMPILER, 'status', '--porcelain').decode(),
                     'baseline_manifest': baseline, 'measured_snapshot': campaign['compiler_snapshot'],
                     'diff_from_baseline': patch, 'before_sources': before, 'changed_sources': after},
        'validation': {'final_summary': final, 'summary_source': artifact(WORK / 'validation-summary.json'),
                       'campaign': campaign['validation'], 'runtime_input_proofs': inputs,
                       'final_archive_checks': checks,
                       'logs': logs},
        'proofs': {'runtime_inputs': proof_files, 'campaign_files': campaign_files,
                   'collectors': collectors,
                   'reference_note': 'C sources, binary and archived medians unchanged; C and JS were not remeasured.'},
        'preservation_note': {'available': 'Original raw measurements, manifests, compiler snapshot, wrapper scripts, generated-code and runtime-input proofs, diagnostics and final test logs are retained in the campaign workspace and archived here.',
                              'reference_catalogue': 'The removed repository catalogue is not restored. The AppAll collector uses the exact archived JS references through the retained wrapper and references.json.'}}
    serialized = json.dumps(archive, ensure_ascii=False, indent=2, allow_nan=False) + '\n'
    if args.write:
        if OUTPUT.exists():
            raise ValueError('Refusing to overwrite existing archive')
        OUTPUT.write_text(serialized)
    print(json.dumps({'written': args.write, 'path': str(OUTPUT), 'bytes': len(serialized.encode()),
                      'sha256': sha(serialized.encode()), 'compiler_changed_sources': changed,
                      'proof_files': len(proof_files), 'validation_logs': len(logs),
                      'compiler_files_verified': checks['compiler_files'],
                      'frozen_current_files_verified': checks['frozen_current_files'],
                      'runtime_input_proofs': inputs}, indent=2))


if __name__ == '__main__':
    main()

