#!/usr/bin/env python3
"""Read-only generated-source comparison, factoring out package assignment."""
from collections import Counter
import difflib
import hashlib
import json
from pathlib import Path
import re
import runpy

WORK = Path(__file__).resolve().parents[2]
COMPARISON = json.loads((WORK / 'proofs/generated-comparison.json').read_text())
LIB = runpy.run_path(str(Path(__file__).with_name('compare-generated.py')))
LEX = re.compile(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`[^`]*`|[A-Za-z_]\w*|[^\s]', re.S)


def tokens(text):
    return [m.group() for m in LEX.finditer(text) if not m.group().startswith(('//', '/*'))]


def normalize_tokens(ts, aliases):
    result, i = [], 0
    while i < len(ts):
        if i + 1 < len(ts) and ts[i + 1] == '.' and ts[i] in aliases:
            target = aliases[ts[i]]
            if target:
                result.extend([target, '.'])
            i += 2
        else:
            result.append(ts[i])
            i += 1
    return result


def inventory(build):
    value = LIB['inventory'](Path(build))
    declarations = []
    for path, section in value['sections'].items():
        header = value['headers'][str(Path(path).parent / '0_gopurs_package.go')].decode()
        aliases = {}
        for alias, target in re.findall(r'^\s*(\w+) "([^"\n]+)"', header, re.M):
            aliases[alias] = ('RUNTIME' if target.endswith('/gopurs_runtime') else ''
                              if '/purescript/' in target else '@' + target)
        text = section.decode()
        matches = [m for m in LEX.finditer(text) if not m.group().startswith(('//', '/*'))]
        depth, starts = 0, []
        for i, match in enumerate(matches):
            token = match.group()
            if depth == 0 and token in ('func', 'var', 'const', 'type') and (match.start() == 0 or text[match.start() - 1] == '\n'):
                starts.append(i)
            if token in ('{', '(', '['): depth += 1
            if token in ('}', ')', ']'): depth -= 1
        if matches and not starts:
            raise ValueError('Unparsed section ' + path)
        for i, begin in enumerate(starts):
            end = starts[i+1] if i+1 < len(starts) else len(matches)
            raw = text[matches[begin].start():matches[end-1].end()]
            declarations.append({'source': path, 'tokens': normalize_tokens(tokens(raw), aliases)})
    return declarations


def key(decl):
    return ' '.join(decl['tokens'][:15])


def compare(scope):
    sets = {variant: inventory(COMPARISON[scope]['builds'][variant]['directory']) for variant in ('before', 'after')}
    counts = {variant: Counter(' '.join(d['tokens']) for d in decls) for variant, decls in sets.items()}
    before, after = counts['before'], counts['after']
    removed = list((before-after).elements())
    added = list((after-before).elements())
    return sets, {'declarations': {k:len(v) for k,v in sets.items()}, 'removed': removed, 'added': added}


def main():
    results = {}
    for scope in ('core', 'all'):
        sets, results[scope] = compare(scope)
        print(scope, 'declarations', results[scope]['declarations'], 'removed', len(results[scope]['removed']), 'added',len(results[scope]['added']))
    (WORK / 'proofs/generated-normalized-review.json').write_text(json.dumps(results,indent=2)+'\n')

if __name__ == '__main__':
    main()

